package io.knowledgebrain.notification;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import io.knowledgebrain.contracts.collaboration.feedbackretraction.v1.*;import io.knowledgebrain.contracts.collaboration.graderetraction.v1.*;
class ReviewLifecycleSignalTest {
 GroupReviewStore.Access a=new GroupReviewStore.Access(ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),ReviewFixtures.ids.next(),1);
 @Test void fourKindsPinRetractionAggregateAndVersionWithoutReasons()throws Exception{var original=ReviewFixtures.feedback(a,1000);for(boolean grade:List.of(false,true))for(String state:List.of("RETRACTED","RESTORED")){var id=ReviewFixtures.ids.next();var bytes=ReviewLifecycleFixtures.event(original,grade,state,2,id,2000);String topic=ReviewSignal.TOPICS.get(grade?4:3);var v=ReviewSignal.decode(topic,bytes);assertEquals((grade?"GRADE_":"FEEDBACK_")+state,v.kind());assertEquals(id,v.aggregateId());assertEquals(2,v.sourceVersion());assertEquals(1,v.submissionVersion());assertFalse(v.toString().contains("PRIVATE"));var headers=Map.of("id",v.eventId().toString(),"trace_id",ReviewFixtures.trace,"schema_group","collaboration","schema_artifact",grade?"grade-retraction-events":"feedback-retraction-events","schema_version","1");ReviewSignal.transport(topic,id.toString(),headers,bytes);assertThrows(IllegalArgumentException.class,()->ReviewSignal.transport(topic,a.groupId().toString(),headers,bytes));assertThrows(IllegalArgumentException.class,()->ReviewSignal.decode(grade?ReviewSignal.TOPICS.get(3):ReviewSignal.TOPICS.get(4),bytes));}}
 @Test void wrongStateTypeActorScopeTargetVersionAndTimesFailClosed()throws Exception{var bytes=ReviewLifecycleFixtures.event(ReviewFixtures.feedback(a,1000),false,"RETRACTED",1,ReviewFixtures.ids.next(),2000);var e=FeedbackRetractionEnvelopeV1.parseFrom(bytes);var p=FeedbackRetractionSnapshotV1.parseFrom(e.getPayload());for(var broken:List.of(e.toBuilder().setEventType("FeedbackRestored").build(),e.toBuilder().setActorId(a.principalId().toString()).build(),e.toBuilder().setSpaceId(a.groupId().toString()).build(),e.toBuilder().setPayload(p.toBuilder().setFeedbackVersion(0).build().toByteString()).build(),e.toBuilder().setPayload(p.toBuilder().setFeedbackId("019A0000-0000-7000-8000-000000000001").build().toByteString()).build(),e.toBuilder().setPayload(p.toBuilder().setState("ACTIVE").build().toByteString()).build(),e.toBuilder().setOccurredAtEpochMillis(2001).build(),e.toBuilder().setEventVersion(2).build()))assertThrows(IllegalArgumentException.class,()->ReviewSignal.decode(ReviewSignal.TOPICS.get(3),broken.toByteArray()));}
 @Test void gradeSelfAnnotationCannotBecomeAnIncomingSignal()throws Exception{var bytes=ReviewLifecycleFixtures.event(ReviewFixtures.feedback(a,1000),true,"RETRACTED",1,ReviewFixtures.ids.next(),2000);var e=GradeRetractionEnvelopeV1.parseFrom(bytes);var p=GradeRetractionSnapshotV1.parseFrom(e.getPayload()).toBuilder().setActorId(a.principalId().toString()).build();assertThrows(IllegalArgumentException.class,()->ReviewSignal.decode(ReviewSignal.TOPICS.get(4),e.toBuilder().setActorId(a.principalId().toString()).setPayload(p.toByteString()).build().toByteArray()));}
}
